package io.knowledgebrain.integration;
import java.net.*;import java.net.http.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import org.mockito.ArgumentMatchers;import org.springframework.web.server.ResponseStatusException;
class GitHubClientTest {
 HttpClient http;HttpResponse<InputStream> response;GitHubClient client;
 @SuppressWarnings("unchecked") @BeforeEach void setup()throws Exception{http=mock(HttpClient.class);when(http.followRedirects()).thenReturn(HttpClient.Redirect.NEVER);response=(HttpResponse<InputStream>)mock(HttpResponse.class);when(response.headers()).thenReturn(HttpHeaders.of(Map.of("Content-Type",List.of("application/json")),(a,b)->true));when(response.statusCode()).thenReturn(200);when(http.send(any(HttpRequest.class),ArgumentMatchers.<HttpResponse.BodyHandler<InputStream>>any())).thenReturn(response);client=new GitHubClient(http,URI.create("https://api.github.com"));}
 void body(String text){when(response.body()).thenAnswer(x->new ByteArrayInputStream(text.getBytes(StandardCharsets.UTF_8)));}
 String repository(){return "{\"id\":1296269,\"private\":false,\"visibility\":\"public\",\"full_name\":\"octocat/Hello-World\",\"html_url\":\"https://github.com/octocat/Hello-World\",\"default_branch\":\"main\"}";}
 @Test void publicMetadataUsesFixedHttpsVersionAndNoAuthentication()throws Exception{body(repository());var v=client.repository("https://github.com/octocat/hello-world");assertEquals("1296269",v.externalId());assertEquals("main",v.defaultBranch());verify(http).send(argThat(q->q.uri().equals(URI.create("https://api.github.com/repos/octocat/hello-world"))&&q.method().equals("GET")&&q.headers().firstValue("Authorization").isEmpty()&&q.headers().firstValue("Cookie").isEmpty()&&q.headers().firstValue("X-GitHub-Api-Version").orElse("").equals("2026-03-10")),ArgumentMatchers.<HttpResponse.BodyHandler<InputStream>>any());}
 @Test void privateMalformedMovedAndDifferentRepositoryMetadataIsRejected(){for(String raw:List.of(repository().replace("\"private\":false","\"private\":true"),repository().replace("\"public\"","\"private\""),repository().replace("1296269","0"),repository().replace("https://github.com/octocat/Hello-World","https://evil.test/a/b"),repository().replace("\"main\"","null"),repository()+" {}")){body(raw);assertThrows(ResponseStatusException.class,()->client.repository("https://github.com/octocat/hello-world"));}}
 @Test void oneBoundedPageKeepsShaGitTimeAndSubjectButNeverEmailOrWholeMessage()throws Exception{String raw="[{\"sha\":\""+"a".repeat(40)+"\",\"author\":{\"login\":\"dependabot[bot]\"},\"commit\":{\"message\":\"Subject <script>\\nPRIVATE BODY\",\"committer\":{\"date\":\"2020-01-01T00:00:00Z\",\"email\":\"not-stored@example.test\"}}}]";body(raw);var batch=client.commits(new GitHubClient.Repository("42","a/b","https://github.com/a/b","feature/branch"));assertEquals(1,batch.commits().size());assertEquals("Subject <script>",batch.commits().getFirst().subject());assertEquals("dependabot[bot]",batch.commits().getFirst().authorLogin());assertFalse(batch.toString().contains("PRIVATE BODY"));assertFalse(batch.toString().contains("email"));assertFalse(batch.possiblyMore());verify(http).send(argThat(q->q.uri().toString().endsWith("/repos/a/b/commits?per_page=20&sha=feature%2Fbranch")),ArgumentMatchers.<HttpResponse.BodyHandler<InputStream>>any());}
 @Test void throttlingRedirectsAndOversizedBodiesFailWithoutAutomaticRetry()throws Exception{body(repository());when(response.statusCode()).thenReturn(429);assertEquals(503,assertThrows(ResponseStatusException.class,()->client.repository("https://github.com/octocat/hello-world")).getStatusCode().value());verify(http,times(1)).send(any(HttpRequest.class),ArgumentMatchers.<HttpResponse.BodyHandler<InputStream>>any());when(response.statusCode()).thenReturn(302);assertEquals(502,assertThrows(ResponseStatusException.class,()->client.repository("https://github.com/octocat/hello-world")).getStatusCode().value());when(response.statusCode()).thenReturn(200);when(response.body()).thenAnswer(x->new ByteArrayInputStream(new byte[2097153]));assertEquals(502,assertThrows(ResponseStatusException.class,()->client.repository("https://github.com/octocat/hello-world")).getStatusCode().value());}
 @Test void stalledBodyIsClosedAtTheTotalDeadlineAndByteReadsRemainBounded()throws Exception{
  var closed=new java.util.concurrent.atomic.AtomicBoolean();var release=new java.util.concurrent.CountDownLatch(1);
  var stalled=new java.io.InputStream(){public int read()throws java.io.IOException{try{release.await();return -1;}catch(InterruptedException e){Thread.currentThread().interrupt();throw new java.io.IOException(e);}}public void close(){closed.set(true);release.countDown();}};
  assertThrows(java.util.concurrent.TimeoutException.class,()->GitHubClient.read(stalled,2,System.nanoTime()+java.time.Duration.ofMillis(20).toNanos()));assertTrue(closed.get());
  assertArrayEquals(new byte[]{1,2},GitHubClient.read(new java.io.ByteArrayInputStream(new byte[]{1,2,3}),2,System.nanoTime()+java.time.Duration.ofSeconds(1).toNanos()));
 }
 @Test void explicitEmptyGitRepositoryIsAnEmptyObservationNotAFabricatedCommit(){when(response.statusCode()).thenReturn(409);body("{\"message\":\"Git Repository is empty.\"}");assertTrue(client.commits(new GitHubClient.Repository("42","a/b","https://github.com/a/b","main")).commits().isEmpty());body("{\"message\":\"Other conflict\"}");assertThrows(ResponseStatusException.class,()->client.commits(new GitHubClient.Repository("42","a/b","https://github.com/a/b","main")));}
 @Test void invalidCommitArraysOrDuplicateShasCannotBePartiallyImported(){body("{}");assertThrows(ResponseStatusException.class,()->client.commits(new GitHubClient.Repository("42","a/b","https://github.com/a/b","main")));body("[]");assertTrue(client.commits(new GitHubClient.Repository("42","a/b","https://github.com/a/b","main")).commits().isEmpty());body("[{}]");assertThrows(ResponseStatusException.class,()->client.commits(new GitHubClient.Repository("42","a/b","https://github.com/a/b","main")));}
}
